package com.trampolim.api.radar;

import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import static com.trampolim.api.radar.RadarModel.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RadarService {
 private final JdbcTemplate jdbc;private final SkillCatalog skills;private final RadarBridge bridge;private final TransactionTemplate tx;private final MatchEngine engine=new MatchEngine();
 private final AtomicLong evaluations=new AtomicLong(),hits=new AtomicLong();
 @Autowired(required=false)void metrics(io.micrometer.core.instrument.MeterRegistry registry){io.micrometer.core.instrument.FunctionCounter.builder("radar.matches.evaluated",evaluations,AtomicLong::doubleValue).register(registry);io.micrometer.core.instrument.FunctionCounter.builder("radar.matches.cache.hits",hits,AtomicLong::doubleValue).register(registry);}
 public RadarService(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog skills,RadarBridge bridge,@Qualifier("oportunidadesTransactionManager")PlatformTransactionManager manager){this.jdbc=jdbc;this.skills=skills;this.bridge=bridge;this.tx=new TransactionTemplate(manager);}
 public record Declaration(String skillCode,int level){}
 public record Preferences(String city,String modality,String area,boolean experienceConfirmed){}
 public record Claim(String challenge,UUID receiptId,String skillCode,int level,String courseTitle,String criterion,String awardedAt){}
 public Policy policy(){var row=jdbc.queryForMap("SELECT revision,weights FROM radar_scoring_policy WHERE id=1");var weights=new LinkedHashMap<String,Integer>();bridge.read(row.get("weights")).fields().forEachRemaining(e->weights.put(e.getKey(),e.getValue().asInt()));return new Policy(((Number)row.get("revision")).intValue(),weights);}
 public void policy(String email,Policy input){skills.admin(email);validateWeights(input.weights());int changed=jdbc.update("UPDATE radar_scoring_policy SET weights=?::jsonb,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=1 AND revision=?",bridge.encode(input.weights()),input.revision());if(changed!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"A regra mudou. Atualize a página.");skills.audit(skills.user(email),"POLICY_UPDATED");}
 public Map<String,Object> profile(String email){long uid=skills.user(email);var result=new LinkedHashMap<String,Object>();var declarations=jdbc.queryForList("SELECT d.skill_code,s.name,d.level,'DECLARED' AS origin,d.updated_at FROM candidate_skill_declarations d JOIN skill_concepts s ON s.code=d.skill_code WHERE user_id=? ORDER BY s.name LIMIT 200",uid);result.put("declarations",declarations);result.put("evidence",evidence(uid));result.put("preferences",preferences(uid));result.put("professionalFacts",facts(uid));
  String text=jdbc.queryForObject("SELECT COALESCE(summary,'') FROM app_users WHERE id=?",String.class,uid);StringBuilder source=new StringBuilder(Objects.toString(text,""));for(var row:jdbc.queryForList("SELECT position,description FROM experiences WHERE user_id=? ORDER BY id DESC LIMIT 50",uid)){if(source.length()>20000)break;source.append(' ').append(row.get("position")).append(' ').append(Objects.toString(row.get("description"),""));}
  String normalized=normalize(source.substring(0,Math.min(20000,source.length())));var suggestions=jdbc.queryForList("SELECT DISTINCT s.code,s.name FROM skill_terms t JOIN skill_concepts s ON s.code=t.skill_code WHERE s.active=TRUE AND position(t.term in ?)>0 AND NOT EXISTS(SELECT 1 FROM candidate_skill_declarations d WHERE d.user_id=? AND d.skill_code=s.code) ORDER BY s.code LIMIT 20",normalized,uid);
  result.put("suggestionsToReview",suggestions);result.put("suggestionsNotice","Sugestões por termos encontrados no perfil, não comprovação. Confirme e corrija antes de declarar. O diagnóstico não define proficiência.");return result;
 }
 private List<Map<String,Object>> evidence(long uid){return jdbc.queryForList("SELECT e.*,s.name FROM candidate_skill_evidence e JOIN skill_concepts s ON s.code=e.skill_code WHERE user_id=? ORDER BY e.skill_code,e.receipt_id LIMIT 100",uid);}
 private Preferences preferences(long uid){return jdbc.query("SELECT city,modality,area,experience_confirmed FROM candidate_radar_preferences WHERE user_id=?",(rs,row)->new Preferences(rs.getString(1),rs.getString(2),rs.getString(3),rs.getBoolean(4)),uid).stream().findFirst().orElse(new Preferences("","","",false));}
 public void preferences(String email,Preferences input){long uid=skills.user(email);if(input==null)bad("Informe suas preferências.");String modality=text(input.modality(),40);if(!modality.isEmpty()&&!Set.of("Presencial","Híbrido","Remoto","Online").contains(modality))bad("Modalidade inválida.");jdbc.update("INSERT INTO candidate_radar_preferences(user_id,city,modality,area,experience_confirmed) VALUES (?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET city=EXCLUDED.city,modality=EXCLUDED.modality,area=EXCLUDED.area,experience_confirmed=EXCLUDED.experience_confirmed,updated_at=CURRENT_TIMESTAMP",uid,text(input.city(),180),modality,text(input.area(),120),input.experienceConfirmed());}
 public void declare(String email,Declaration input){long uid=skills.user(email);if(input==null||input.skillCode()==null||input.level()<1||input.level()>4)bad("Nível entre 1 e 4.");skills.validateCodes(List.of(input.skillCode()));tx.executeWithoutResult(status->{jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM candidate_skill_declarations WHERE user_id=?",Integer.class,uid)>=200&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM candidate_skill_declarations WHERE user_id=? AND skill_code=?)",Boolean.class,uid,input.skillCode())))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de competências declaradas atingido.");jdbc.update("INSERT INTO candidate_skill_declarations(user_id,skill_code,level) VALUES (?,?,?) ON CONFLICT(user_id,skill_code) DO UPDATE SET level=EXCLUDED.level,updated_at=CURRENT_TIMESTAMP",uid,input.skillCode(),input.level());skills.audit(uid,"SKILL_DECLARED");});}
 public void removeDeclaration(String email,String code){jdbc.update("DELETE FROM candidate_skill_declarations WHERE user_id=? AND skill_code=?",skills.user(email),code);}
 public void removeEvidence(String email,UUID id){jdbc.update("DELETE FROM candidate_skill_evidence WHERE user_id=? AND receipt_id=?",skills.user(email),id);}
 public Map<String,Object> challenge(String email){bridge.configured();long uid=skills.user(email);return tx.execute(status->{jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM radar_claim_challenges WHERE user_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 hour'",Integer.class,uid)>=10)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Aguarde antes de gerar outro código.");jdbc.update("DELETE FROM radar_claim_challenges WHERE user_id=? AND expires_at<CURRENT_TIMESTAMP-INTERVAL '1 day'",uid);String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");jdbc.update("INSERT INTO radar_claim_challenges(token_hash,user_id,expires_at) VALUES (?,?,CURRENT_TIMESTAMP+INTERVAL '15 minutes')",RadarBridge.hash(token),uid);skills.audit(uid,"LINK_CHALLENGE_CREATED");return Map.of("challenge",token,"expiresInMinutes",15);});}
 public Map<String,Object> accept(String key,Claim input){bridge.authorize(key);if(input==null||input.challenge()==null||!input.challenge().matches("[a-f0-9]{64}")||input.receiptId()==null||input.skillCode()==null||input.level()<1||input.level()>4)bad("Comprovação inválida.");skills.validateCodes(List.of(input.skillCode()));Instant awarded;try{awarded=Instant.parse(input.awardedAt());if(awarded.isAfter(Instant.now().plusSeconds(60)))throw new IllegalArgumentException();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Data de conquista inválida.");}
  return tx.execute(status->{var rows=jdbc.queryForList("SELECT * FROM radar_claim_challenges WHERE token_hash=? AND expires_at>CURRENT_TIMESTAMP FOR UPDATE",RadarBridge.hash(input.challenge()));if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Código expirado ou inválido. Gere outro em Oportunidades.");var row=rows.get(0);long uid=((Number)row.get("user_id")).longValue();Object used=row.get("used_receipt");if(used!=null){if(!used.equals(input.receiptId())||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM candidate_skill_evidence WHERE receipt_id=? AND user_id=?)",Boolean.class,input.receiptId(),uid)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código já utilizado.");return Map.of("status","IMPORTED");}
   jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM candidate_skill_evidence WHERE user_id=?",Integer.class,uid)>=100)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de comprovações atingido.");
   jdbc.update("INSERT INTO candidate_skill_evidence(receipt_id,user_id,skill_code,level,origin,course_title,criterion,awarded_at) VALUES (?,?,?,?,'CAPACITA',?,?,?)",input.receiptId(),uid,input.skillCode(),input.level(),text(input.courseTitle(),180),text(input.criterion(),2000),java.sql.Timestamp.from(awarded));jdbc.update("UPDATE radar_claim_challenges SET used_receipt=? WHERE token_hash=?",input.receiptId(),RadarBridge.hash(input.challenge()));skills.audit(uid,"CAPACITA_EVIDENCE_CONSENTED");return Map.of("status","IMPORTED");});
 }
 public Map<String,Object> facts(long uid){var experience=jdbc.queryForList("SELECT start_date,end_date,is_current FROM experiences WHERE user_id=? ORDER BY start_date,id LIMIT 201",uid);List<int[]> intervals=new ArrayList<>();int invalid=0,now=month(YearMonth.now());for(var row:experience){try{int start=month(YearMonth.parse(Objects.toString(row.get("start_date"),""))),end=Boolean.TRUE.equals(row.get("is_current"))?now:month(YearMonth.parse(Objects.toString(row.get("end_date"),"")));if(start>now||end>now||end<start)throw new IllegalArgumentException();intervals.add(new int[]{start,end});}catch(Exception ignored){invalid++;}}
  intervals.sort(Comparator.comparingInt(a->a[0]));int total=0,left=-1,right=-1;for(var interval:intervals){if(left<0){left=interval[0];right=interval[1];}else if(interval[0]<=right)right=Math.max(right,interval[1]);else{total+=right-left;left=interval[0];right=interval[1];}}if(left>=0)total+=right-left;
  int education=0,unrecognized=0;for(var row:jdbc.queryForList("SELECT level FROM educations WHERE user_id=? AND in_progress=FALSE LIMIT 200",uid)){String level=normalize(Objects.toString(row.get("level"),""));int rank=switch(level){case "fundamental","ensino fundamental"->1;case "medio","ensino medio"->2;case "tecnico","ensino tecnico","curso tecnico"->3;case "superior","ensino superior","graduacao","bacharelado","licenciatura","tecnologo"->4;case "pos-graduacao","pos graduacao","mestrado","doutorado","especializacao"->5;default->0;};education=Math.max(education,rank);if(rank==0)unrecognized++;}
  var result=new LinkedHashMap<String,Object>();result.put("experienceMonths",experience.size()>200?null:!experience.isEmpty()&&intervals.isEmpty()?null:experience.isEmpty()&&!preferences(uid).experienceConfirmed()?null:total);result.put("educationLevel",education==0?null:education);result.put("invalidExperienceDates",invalid);result.put("unrecognizedEducationEntries",unrecognized);result.put("notice","Experiência geral em meses completos aproximados, sem sobreposição; somente formação concluída reconhecida. Tudo declarado, sem equivalência a licença profissional. Revise dados no perfil.");return result;
 }
 private int month(YearMonth value){return value.getYear()*12+value.getMonthValue();}
 private Job catalogJob(long id){return jdbc.query("SELECT c.id,c.title,c.provider,c.area,c.location,c.modality,c.description,c.updated_at,r.definition FROM catalog_items c LEFT JOIN radar_catalog_requirements r ON r.item_id=c.id WHERE c.id=? AND c.kind='job' AND c.active=TRUE AND c.moderation_status='APPROVED' AND (c.expires_at IS NULL OR c.expires_at>=?)",(rs,row)->new Job("catalog",rs.getLong(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getObject(9)==null?Requirements.empty():bridge.convert(bridge.read(rs.getObject(9)),Requirements.class),rs.getTimestamp(8).toInstant().toString()),id,java.sql.Date.valueOf(LocalDate.now(ZoneId.of("America/Sao_Paulo")))).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Vaga não disponível."));}
 private void source(String value){if(!Set.of("catalog","company").contains(value))bad("Fonte de vaga inválida.");}
 public Job job(String source,long id){source(source);if(id<1)bad("Vaga inválida.");return source.equals("catalog")?catalogJob(id):bridge.convert(bridge.get("/public/companies/radar-jobs/"+id),Job.class);}
 public Map<String,Object> jobs(String email,String source,long before,int limit,String q){skills.user(email);source(source);text(q,120);if(before<1||limit<1||limit>50)bad("Consulta inválida.");if(source.equals("company"))return bridge.convert(bridge.get("/public/companies/radar-jobs?before="+before+"&limit="+limit+"&q="+java.net.URLEncoder.encode(q,java.nio.charset.StandardCharsets.UTF_8)),Map.class);
  var rows=jdbc.queryForList("SELECT id,title,provider AS company,area,location,modality FROM catalog_items WHERE id<? AND kind='job' AND active=TRUE AND moderation_status='APPROVED' AND (expires_at IS NULL OR expires_at>=?) AND (?='' OR title ILIKE ? OR area ILIKE ?) ORDER BY id DESC LIMIT ?",before,java.sql.Date.valueOf(LocalDate.now(ZoneId.of("America/Sao_Paulo"))),q,"%"+q+"%","%"+q+"%",limit+1);var result=new LinkedHashMap<String,Object>();result.put("items",rows.stream().limit(limit).toList());result.put("nextCursor",rows.size()>limit?rows.get(limit-1).get("id"):null);return result;
 }
 public Requirements catalogRequirements(String email,long id){skills.admin(email);return storedRequirements(id);}
 private Requirements storedRequirements(long id){var rows=jdbc.queryForList("SELECT definition FROM radar_catalog_requirements WHERE item_id=?",id);return rows.isEmpty()?Requirements.empty():bridge.convert(bridge.read(rows.get(0).get("definition")),Requirements.class);}
 public void catalogRequirements(String email,long id,Requirements input){skills.admin(email);var definition=validate(input);skills.validateCodes(definition.skills().stream().map(Need::skillCode).toList());tx.executeWithoutResult(status->{if(jdbc.queryForList("SELECT id FROM catalog_items WHERE id=? AND kind='job' FOR UPDATE",id).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);int revision=storedRequirements(id).revision();if(revision!=definition.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Critérios desatualizados.");var next=new Requirements(revision+1,definition.skills(),definition.experienceMonths(),definition.educationLevel(),definition.experienceEliminatory(),definition.educationEliminatory(),definition.city(),definition.modality(),definition.area());jdbc.update("INSERT INTO radar_catalog_requirements(item_id,revision,definition) VALUES (?,?,?::jsonb) ON CONFLICT(item_id) DO UPDATE SET revision=EXCLUDED.revision,definition=EXCLUDED.definition,updated_at=CURRENT_TIMESTAMP",id,next.revision(),bridge.encode(next));skills.audit(skills.user(email),"JOB_REQUIREMENTS_UPDATED");});}
 public Map<String,Object> match(String email,String source,long id){return analyze(email,job(source,id));}
 public Map<String,Object> matchFuture(String email,Job job){if(!"future".equals(job.source()))bad("Previsão inválida.");return analyze(email,job);}
 private Map<String,Object> analyze(String email,Job job){String source=job.source();long id=job.id();long uid=skills.user(email);Preferences pref=preferences(uid);var facts=facts(uid);var levels=new TreeMap<String,Level>();for(var row:jdbc.queryForList("SELECT skill_code,level FROM candidate_skill_declarations WHERE user_id=? ORDER BY skill_code LIMIT 200",uid))levels.put(row.get("skill_code").toString(),new Level(((Number)row.get("level")).intValue(),0));
  var evidence=evidence(uid);String evidenceStatus="OK";if(!evidence.isEmpty()){try{var valid=bridge.post("/integrations/capacita/radar/evidence",Map.of("receipts",evidence.stream().map(row->row.get("receipt_id")).toList()));for(var row:valid){if(!row.path("active").asBoolean())continue;String code=row.path("skillCode").asText();var local=evidence.stream().filter(item->item.get("receipt_id").toString().equals(row.path("receiptId").asText())&&item.get("skill_code").equals(code)&&((Number)item.get("level")).intValue()==row.path("level").asInt()).findFirst();if(local.isEmpty())continue;var prior=levels.getOrDefault(code,new Level(0,0));levels.put(code,new Level(prior.declared(),Math.max(prior.verified(),row.path("level").asInt())));}}catch(ResponseStatusException error){evidenceStatus="UNAVAILABLE";}}
  var candidate=new Candidate(levels,(Integer)facts.get("experienceMonths"),(Integer)facts.get("educationLevel"),pref.city(),pref.modality(),pref.area());var policy=policy();String fingerprint=RadarBridge.hash(bridge.encode(List.of(candidate,job,policy,evidenceStatus)));
  Map<String,Object> analysis=tx.execute(status->{jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,row)->0,"radar:"+uid+":"+source+":"+id);var cached=jdbc.queryForList("SELECT result FROM radar_match_cache WHERE user_id=? AND source=? AND job_id=? AND fingerprint=?",uid,source,id,fingerprint);if(!cached.isEmpty()){hits.incrementAndGet();return bridge.convert(bridge.read(cached.get(0).get("result")),Map.class);}var value=engine.evaluate(candidate,job.requirements(),policy);value.put("evaluatedAt",Instant.now().toString());jdbc.update("INSERT INTO radar_match_cache(user_id,source,job_id,fingerprint,result) VALUES (?,?,?,?,?::jsonb) ON CONFLICT(user_id,source,job_id) DO UPDATE SET fingerprint=EXCLUDED.fingerprint,result=EXCLUDED.result,evaluated_at=CURRENT_TIMESTAMP",uid,source,id,fingerprint,bridge.encode(value));jdbc.update("DELETE FROM radar_match_cache WHERE user_id=? AND (source,job_id) IN (SELECT source,job_id FROM radar_match_cache WHERE user_id=? ORDER BY evaluated_at DESC OFFSET 200)",uid,uid);evaluations.incrementAndGet();return value;});
  var gapCodes=new LinkedHashSet<String>();for(var row:(List<Map<String,Object>>)analysis.get("skills"))if(!"MET".equals(row.get("status")))gapCodes.add(row.get("skillCode").toString());
  var result=new LinkedHashMap<String,Object>();result.put("job",job);result.put("analysis",analysis);result.put("evidenceStatus",evidenceStatus);result.put("professionalFacts",facts);result.put("catalog",skills.resolve(job.requirements().skills().stream().map(Need::skillCode).toList()));
  if(gapCodes.isEmpty())result.put("training",Map.of("status","NO_GAPS","items",List.of()));else try{result.put("training",Map.of("status","AVAILABLE","items",bridge.convert(bridge.get("/public/capacita/radar/training?codes="+String.join(",",gapCodes)),List.class)));}catch(ResponseStatusException error){result.put("training",Map.of("status","UNAVAILABLE","items",List.of()));}return result;
 }
 public Map<String,Object> export(String email){long uid=jdbc.queryForObject("SELECT id FROM app_users WHERE LOWER(email)=LOWER(?)",Long.class,email);return Map.of("declarations",jdbc.queryForList("SELECT skill_code,level,updated_at FROM candidate_skill_declarations WHERE user_id=?",uid),"evidence",evidence(uid),"preferences",preferences(uid));}
 public long evaluationCount(){return evaluations.get();}public long cacheHitCount(){return hits.get();}
}
